defined( 'ABSPATH' ) || exit;

function co_sales_documents_page() {
	if ( ! current_user_can( 'edit_posts' ) ) return;
	$type = sanitize_key( $_GET['type'] ?? 'quotation' );
	if ( ! isset( co_sales_types()[$type] ) ) $type = 'quotation';
	if ( 'quotation' === $type && 'trash' === ( $_GET['view'] ?? '' ) ) { co_sales_quote_trash_page(); return; }
	$issuer_filter = sanitize_key( $_GET['issuer'] ?? '' );
	$documents = co_sales_filtered_documents( $type, $issuer_filter );
	$has_wht = in_array( $type, array( 'quotation', 'invoice' ), true );
	$invoice_rows = array(); $file_counts = array();
	if ( $has_wht ) foreach ( $documents as $document ) { $invoice_rows[$document->ID] = co_sales_wht_document_invoices( $document->ID ); $file_counts[$document->ID] = co_sales_wht_listing_summary( $invoice_rows[$document->ID] )['files']; }
	co_sales_assets(); ?>
	<div class="sales-wrap"><header class="sales-hero compact"><div><small>SALES DOCUMENTS</small><h1><?php echo esc_html( co_sales_types()[$type] ); ?></h1><p>ใบเสนอราคา ใบแจ้งหนี้ และใบเสร็จรับเงิน</p></div><a class="sales-btn white" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-edit&type=' . $type ) ); ?>">+ สร้าง <?php echo esc_html( co_sales_types()[$type] ); ?></a></header>
	<nav class="sales-tabs"><?php foreach ( co_sales_types() as $key => $label ) : ?><a class="<?php echo $key === $type ? 'active' : ''; ?>" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents&type=' . $key . '&issuer=' . rawurlencode( $issuer_filter ) ) ); ?>"><?php echo esc_html( $label ); ?></a><?php endforeach; ?><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-clients' ) ); ?>">ลูกค้า</a><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-settings' ) ); ?>">ตั้งค่าผู้ออกเอกสาร</a><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-wht&issuer=' . rawurlencode( $issuer_filter ) ) ); ?>">ใบหัก ณ ที่จ่าย</a></nav>
	<?php if ( 'quotation' === $type ) : ?><div class="sales-lifecycle-notice"><?php if ( 'trash' === ( $_GET['lifecycle'] ?? '' ) ) : ?><span role="status">ย้าย QO ลงถังขยะแล้ว สามารถกู้คืนได้</span><?php elseif ( 'restore' === ( $_GET['lifecycle'] ?? '' ) ) : ?><span role="status">กู้คืน QO แล้ว</span><?php endif; ?><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents&type=quotation&view=trash' ) ); ?>">ถังขยะ Quotation →</a></div><?php endif; ?>
	<?php if ( $has_wht ) co_project_render_tasks(); ?>
	<section class="sales-panel sales-document-list-panel"><div class="sales-list-heading"><h2><?php echo esc_html( co_sales_types()[$type] ); ?> (<?php echo count( $documents ); ?>)</h2><form class="sales-form sales-wht-filters" method="get" action="<?php echo esc_url( admin_url( 'admin.php' ) ); ?>"><input type="hidden" name="page" value="co-sales-documents"><input type="hidden" name="type" value="<?php echo esc_attr( $type ); ?>"><label>ผู้ออก <?php echo esc_html( co_sales_types()[$type] ); ?><select name="issuer"><option value="">ทุกคน</option><?php foreach ( co_sales_issuer_filters() as $key => $name ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $issuer_filter, $key ); ?>><?php echo esc_html( $name ); ?></option><?php endforeach; ?></select></label><button class="sales-btn" type="submit">กรอง</button><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents&type=' . $type ) ); ?>">ล้างตัวกรอง</a></form></div>
	<?php if ( $has_wht ) : ?><form data-wht-bulk-form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'co_sales_wht_archive' ); ?><input type="hidden" name="action" value="co_sales_wht_archive"><input type="hidden" name="collection_mode" value="selected"><input type="hidden" name="document_type" value="<?php echo esc_attr( $type ); ?>"><input type="hidden" name="issuer" value="<?php echo esc_attr( $issuer_filter ); ?>"><?php co_sales_wht_bulk_toolbar( $type, $issuer_filter, array_sum( $file_counts ) > 0 ); ?><?php endif; ?>
	<div class="sales-table-wrap"><table class="<?php echo $has_wht ? 'sales-documents-with-wht' : ''; ?>"><thead><tr><?php if ( $has_wht ) : ?><th class="sales-wht-select-cell">เลือก</th><?php endif; ?><th>เลขที่เอกสาร / ลูกค้า</th><th>Project</th><th>ผู้ออกเอกสาร</th><th>วันที่</th><th>จำนวนเงินรวมทั้งสิ้น</th><th>ติดตามเอกสาร</th><?php if ( $has_wht ) : ?><th>ใบภาษี</th><?php endif; ?><th></th></tr></thead><tbody>
	<?php foreach ( $documents as $document ) : $id = $document->ID; $client = co_sales_meta( $id, 'client_snapshot', array() ); ?><tr>
	<?php if ( $has_wht ) : ?><td class="sales-wht-select-cell"><input type="checkbox" name="document_ids[]" value="<?php echo $id; ?>" data-wht-select <?php disabled( ! $file_counts[$id] ); ?> aria-label="เลือกใบหักภาษีของ <?php echo esc_attr( co_sales_meta( $id, 'number' ) ); ?>"></td><?php endif; ?>
	<td class="sales-document-title-cell"><strong><?php echo esc_html( co_sales_meta( $id, 'number' ) ); ?></strong><small class="sales-amount-before"><?php echo esc_html( $client['name'] ?? get_the_title( co_sales_meta( $id, 'client_id' ) ) ); ?></small></td><td data-label="Project"><?php echo esc_html( get_the_title( absint( co_sales_meta( $id, 'project_id' ) ) ) ); ?></td><td data-label="ผู้ออกเอกสาร"><?php echo esc_html( co_sales_document_issuer( $id )['name'] ); ?></td><td data-label="วันที่"><?php echo esc_html( co_sales_date( co_sales_meta( $id, 'issue_date' ) ) ); ?></td><td data-label="ยอดสุทธิ">฿<?php echo esc_html( co_sales_money( co_sales_grand_total( $id ) ) ); ?></td><td class="sales-tracking-cell" data-label="ติดตามเอกสาร"><?php co_sales_render_listing_tracking( $id, $type ); ?></td>
	<?php if ( $has_wht ) : ?><td data-label="ใบภาษี"><?php co_sales_wht_listing_badge( $invoice_rows[$id] ); ?></td><?php endif; ?><td><div class="sales-row-actions"><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-edit&document=' . $id ) ); ?>">เปิดเอกสาร →</a><?php if ( 'quotation' === $type ) co_sales_quote_action_button( $id ); ?></div></td></tr><?php endforeach; if ( ! $documents ) : ?><tr><td colspan="<?php echo $has_wht ? 9 : 7; ?>">ไม่พบเอกสารตามตัวกรอง</td></tr><?php endif; ?>
	</tbody></table></div><?php if ( $has_wht ) : ?></form><?php endif; ?></section><?php if ( 'quotation' === $type ) foreach ( $documents as $document ) co_sales_quote_action_form( $document->ID ); ?></div>
<?php }

function co_sales_edit_page() {
	if ( ! current_user_can( 'edit_posts' ) ) return;
	$id = absint( $_GET['document'] ?? 0 );
	if ( $id && ( 'sales_document' !== get_post_type( $id ) || 'publish' !== get_post_status( $id ) ) ) wp_die( 'Document not found.' );
	$type = $id ? co_sales_meta( $id, 'document_type' ) : sanitize_key( $_GET['type'] ?? 'quotation' );
	if ( ! isset( co_sales_types()[$type] ) ) $type = 'quotation';
	$project_id = $id ? absint( co_sales_meta( $id, 'project_id' ) ) : absint( $_GET['project'] ?? 0 );
	if ( ! $id && 'receipt' === $type ) {
		co_sales_assets(); echo '<div class="sales-wrap"><section class="sales-panel"><h1>ออก Receipt จากรายการรับเงิน</h1><p>เปิด Invoice ของงวดที่รับเงินแล้ว แล้วกดออก Receipt เพื่อไม่ให้ยอดรับเงินซ้ำ</p><a class="sales-btn" href="' . esc_url( admin_url( 'admin.php?page=co-sales-documents&type=invoice' ) ) . '">เลือก Invoice →</a></section></div>'; return;
	}
	$items = $id ? co_sales_items( $id ) : co_sales_default_items();
	if ( ! $id && $project_id ) $items[0]['amount'] = co_crm_meta( $project_id, 'net_total' );
	$schedule = $id ? co_sales_billing_schedule( $id ) : ( 'quotation' === $type ? co_sales_parse_schedule( co_sales_default_schedule_text() ) : array( array( 'percent' => 100, 'description' => '' ) ) );
	if ( ! $schedule ) $schedule = array( array( 'percent' => '', 'description' => '' ) );
	co_sales_assets(); ?>
	<div class="sales-wrap"><header class="sales-edit-head"><div><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-documents&type=' . $type ) ); ?>">← <?php echo esc_html( co_sales_types()[$type] ); ?></a><h1><?php echo esc_html( $id ? co_sales_meta( $id, 'number' ) : 'สร้าง ' . co_sales_types()[$type] ); ?></h1></div><div><?php if ( $id ) : ?><a class="sales-btn light" target="_blank" href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-preview&document=' . $id ) ); ?>">Preview / PDF ↗</a><?php if ( 'invoice' === $type && co_sales_invoice_payment( $id ) && ! co_sales_invoice_receipt( $id ) ) : ?><a class="sales-btn" data-sales-confirm="สร้าง Receipt เมื่อได้รับชำระเงินแล้ว?" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=co_sales_derive_document&source=' . $id ), 'co_sales_derive_' . $id ) ); ?>">สร้าง Receipt</a><?php endif; endif; ?></div></header>
	<?php if ( $id && 'quotation' === $type ) : ?><div class="sales-lifecycle-notice"><?php co_sales_quote_action_button( $id ); ?><?php $delete_reason = co_sales_quote_delete_reason( $id ); if ( $delete_reason ) : ?><small><?php echo esc_html( $delete_reason ); ?></small><?php else : ?><small>ลบทั้งชุด QO, Invoice, Receipt และรายการรับเงิน ไม่ลบ Project หรือ MA</small><?php endif; ?></div><?php co_sales_quote_action_form( $id ); endif; ?>
	<?php if ( $id && 'quotation' === $type ) { co_project_render_accept( $id, $project_id ); co_sales_render_quote_progress( $id ); } elseif ( $id && 'invoice' === $type ) co_sales_render_invoice_progress( $id ); ?>
	<?php if ( $id ) co_sales_render_wht( $id ); ?>
	<?php if ( $project_id ) : ?><p><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-projects&open_project=' . $project_id ) ); ?>">← กลับไป Project นี้</a></p><?php endif; ?>
	<?php if ( $id && co_sales_financial_locked( $id ) ) : ?><p class="sales-billing-warning">ราคา ลูกค้า Project และแผนงวดล็อกตามข้อตกลงแล้ว ยังคงแก้รายละเอียดงานและวันที่เอกสารได้ โดยไม่เปลี่ยนวันที่รับเงินจริง</p><?php endif; ?>
	<form data-price-total="<?php echo esc_attr( co_sales_document_breakdown( $id )['price'] ); ?>" data-rounding-adjustment="<?php echo esc_attr( co_sales_meta( $id, 'rounding_adjustment', 0 ) ); ?>" data-wht-amount="<?php echo esc_attr( co_sales_wht( $id ) ); ?>" class="sales-form sales-document-form" data-financial-locked="<?php echo $id && co_sales_financial_locked( $id ) ? '1' : '0'; ?>" data-document-type="<?php echo esc_attr( $type ); ?>" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'co_sales_document' ); ?><input type="hidden" name="action" value="co_sales_save_document"><input type="hidden" name="document_id" value="<?php echo $id; ?>"><input type="hidden" name="source_document_id" value="<?php echo absint( co_sales_meta( $id, 'source_document_id' ) ); ?>">
	<section class="sales-panel"><h2>ข้อมูลเอกสาร</h2><div class="sales-grid">
	<label>ประเภทเอกสาร<?php if ( $id ) : ?><input readonly value="<?php echo esc_attr( co_sales_types()[$type] ); ?>"><input type="hidden" name="document_type" value="<?php echo esc_attr( $type ); ?>"><?php else : ?><select name="document_type" data-type-select><?php foreach ( co_sales_types() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>" <?php selected( $type, $key ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select><?php endif; ?></label>
	<label>ลูกค้า *<select required name="client_id"><option value="">เลือกลูกค้า</option><?php foreach ( co_sales_clients() as $client ) : ?><option value="<?php echo $client->ID; ?>" <?php selected( co_sales_meta( $id, 'client_id', get_post_meta( $project_id, '_crm_sales_client_id', true ) ), $client->ID ); ?>><?php echo esc_html( $client->post_title ); ?></option><?php endforeach; ?></select><a href="<?php echo esc_url( admin_url( 'admin.php?page=co-sales-clients' ) ); ?>">เพิ่ม / แก้ไขข้อมูลลูกค้า</a></label>
	<label>Project<select name="project_id"><option value="">ไม่เชื่อม Project</option><?php foreach ( co_crm_projects() as $project ) : ?><option value="<?php echo $project->ID; ?>" <?php selected( $project_id, $project->ID ); ?>><?php echo esc_html( $project->post_title ); ?></option><?php endforeach; ?></select></label>
	<label>ผู้ออกเอกสาร *<select required name="issuer_id" data-issuer-locked="<?php echo $id && ( co_sales_financial_locked( $id ) || co_sales_wht_files( $id, true ) ) ? '1' : '0'; ?>"><?php $saved_issuer = co_sales_meta( $id, 'issuer_id' ); if ( $saved_issuer && ! in_array( $saved_issuer, array_column( co_sales_issuers(), 'id' ), true ) ) : ?><option selected value="<?php echo esc_attr( $saved_issuer ); ?>"><?php echo esc_html( co_sales_document_issuer( $id )['name'] ); ?> (ข้อมูลเดิม)</option><?php endif; ?><?php foreach ( co_sales_issuers() as $issuer ) : ?><option value="<?php echo esc_attr( $issuer['id'] ); ?>" <?php selected( co_sales_meta( $id, 'issuer_id' ), $issuer['id'] ); ?>><?php echo esc_html( $issuer['name'] ?: 'ตั้งค่าผู้ออกเอกสาร' ); ?></option><?php endforeach; ?></select></label>
	<label>วันที่เอกสาร<input required type="date" name="issue_date" value="<?php echo esc_attr( $id ? co_sales_meta( $id, 'issue_date', wp_date( 'Y-m-d' ) ) : wp_date( 'Y-m-d' ) ); ?>"></label><label data-document-installment <?php echo 'quotation' === $type ? 'hidden' : ''; ?>>งวดที่<input min="1" type="<?php echo 'quotation' === $type ? 'hidden' : 'number'; ?>" name="installment_no" value="<?php echo 'quotation' === $type ? 0 : max( 1, absint( co_sales_meta( $id, 'installment_no', 1 ) ) ); ?>"></label></div>
	<label><span data-document-title-label><?php echo 'quotation' === $type ? 'ชื่องาน / ชื่อใบเสนอราคา' : 'หัวข้อรายการ / รายละเอียดงวด'; ?></span><input name="document_title" value="<?php echo esc_attr( co_sales_meta( $id, 'title', $project_id ? get_the_title( $project_id ) : 'Website Design & Development' ) ); ?>"><small class="sales-field-help" data-document-title-help><?php echo 'quotation' === $type ? 'ชื่องานสำหรับอ้างอิงในระบบ ส่วนรายละเอียดที่พิมพ์ใน Quotation ให้กรอกในรายการงานด้านล่าง' : 'หัวข้อนี้จะแสดงก่อนรายละเอียดงานใน ' . co_sales_types()[$type]; ?></small></label></section>
	<section class="sales-panel"><div class="sales-panel-head"><div><h2>คำอธิบายและมูลค่างาน</h2><p>แก้ข้อความและราคาของแต่ละรายการได้ ระบบแบ่งหน้าให้อัตโนมัติ</p></div><button type="button" class="sales-btn light" data-add-item>+ เพิ่มรายการ</button></div><button type="button" class="sales-link" data-use-original-template>ใช้รายละเอียดตั้งต้นครบตามต้นฉบับ</button><template data-sales-default-items><?php foreach ( co_sales_default_items() as $index => $item ) co_sales_item_editor( $item, $index ); ?></template><div data-sales-items><?php foreach ( $items as $index => $item ) co_sales_item_editor( $item, $index ); ?></div>
	<section class="sales-discount-section"><h2>ราคาและส่วนลด</h2><div class="sales-discount-grid"><label>รวมราคาทุกรายการ (บาท)<input readonly data-sales-base-total value="<?php echo esc_attr( co_sales_items_value( $items ) ); ?>"></label><label>ส่วนลดทั้งงาน (บาท)<input name="discount" type="number" min="0" step=".01" value="<?php echo esc_attr( co_sales_meta( $id, 'discount', 0 ) ); ?>" placeholder="0" aria-describedby="sales-discount-help"></label><label>ยอดหลังส่วนลด (บาท)<input readonly data-sales-net-base></label></div><p id="sales-discount-help">หักส่วนลดจากมูลค่าทั้งงานก่อนแบ่งงวดและหัก ณ ที่จ่าย หากไม่มีส่วนลดให้ใส่ 0</p><div data-billing-base-panel <?php echo 'quotation' === $type ? 'hidden' : ''; ?>><p class="sales-billing-formula" data-billing-formula></p></div></section>
	<section class="sales-schedule" data-sales-schedule><div class="sales-panel-head"><div><h2 data-schedule-heading><?php echo 'quotation' === $type ? 'แผนงวดชำระเงิน / Terms of Payment' : 'งวดที่เรียกเก็บในใบนี้'; ?></h2><p>กรอกเปอร์เซ็นต์และเงื่อนไข ระบบคำนวณมูลค่างวดจากยอดหลังส่วนลดให้ทันที</p></div><button type="button" class="sales-btn light" data-add-schedule <?php echo 'quotation' !== $type ? 'hidden' : ''; ?>>+ เพิ่มงวด</button></div>
	<div data-schedule-rows><?php foreach ( $schedule as $index => $row ) : ?>
	<div class="sales-schedule-row" data-schedule-row><strong data-schedule-label>งวดที่ <?php echo $index + 1; ?></strong><label>เปอร์เซ็นต์ (%)<input name="schedule_percent[]" type="number" min="0.01" max="100" step=".01" value="<?php echo esc_attr( $row['percent'] ); ?>" placeholder="100"></label><label>เงื่อนไขการชำระ<textarea name="schedule_description[]" rows="2" placeholder="เช่น หลังเซ็นสัญญาใบเสนอราคา"><?php echo esc_textarea( $row['description'] ); ?></textarea></label><div class="sales-schedule-amount"><small>มูลค่าก่อนหัก</small><strong data-schedule-amount></strong></div><button type="button" class="sales-link danger" data-remove-schedule>ลบงวด</button></div>
	<?php endforeach; ?></div><p data-schedule-total aria-live="polite"></p><div class="sales-schedule-preview"><strong>ตัวอย่างที่จะแสดงใน PDF</strong><div data-schedule-preview aria-live="polite"></div></div></section>
	<div class="sales-grid finance"><label><span data-subtotal-label><?php echo 'quotation' === $type ? 'ราคาสุทธิหลังส่วนลด' : 'มูลค่างวดนี้หลังส่วนลด (คำนวณอัตโนมัติ)'; ?></span><input required min="0" step=".01" type="number" name="subtotal" readonly value="<?php echo esc_attr( co_sales_document_total( $id ) ); ?>"></label><label>หัก ณ ที่จ่าย (%)<input type="number" min="0" max="100" step=".01" name="wht_rate" value="<?php echo esc_attr( co_sales_meta( $id, 'wht_rate', 3 ) ); ?>"></label><div><small>จำนวนหัก ณ ที่จ่าย</small><strong>฿<span data-sales-wht></span></strong></div><div><small>จำนวนเงินรวมทั้งสิ้น</small><strong>฿<span data-sales-total></span></strong></div></div>
